INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l42','take a bath','have a bath','洗澡;美语 take a bath,英式 have a bath') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l42','take a rest','have a rest','休息;美语 take a rest / take a break,英式 have a rest(课文 have a rest)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l42','take a look','have a look','看一看;美语 take a look 更常见,英式 have a look(课文 have a look)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l42','have / have got','',NULL,'/hæv ɡɑːt/','He has got a new house.','他有一座新房子。','I have got two large baskets.','我有两个大筐。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l42','have + 名词 = 做某事','',NULL,'/hæv/','We had a good time at the party.','我们在聚会上玩得很开心。','He wanted to have a drink of water.','他想喝点水。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l42','pick up','',NULL,'/pɪk ʌp/','He picked up a long pipe.','他拿起一根长管。','I picked up a lot of English in England.','我在英国学了不少英语。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l42','tell the difference between','',NULL,'/tel ðə ˈdɪfərəns/','It could not tell the difference between Indian music and jazz.','它分辨不出印度音乐和爵士乐。','Can you tell the difference between them?','你能分辨它们吗?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp1','choice','{"stem":"\"He owns a new house. = He ___ a new house.\"(表''拥有'')","options":["is","does","gets","has"],"answer_index":3,"stem_cn":"他有一座新房子。","explanation_cn":"have 可替换 own 表\"拥有\"。✓ He has a new house 他有一座新房子。✗ is:那是\"是\";✗ does / gets:不表\"拥有\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp1','choice','{"stem":"\"He possesses a lot of money. = He ___ a lot of money.\"(表''拥有'')","options":["is","has","does","makes"],"answer_index":1,"stem_cn":"他有很多钱。","explanation_cn":"have 可替换 possess 表\"拥有\"。✓ He has a lot of money 他有很多钱。✗ is:是\"是\";✗ does / makes:不表\"拥有\"。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp2','choice','{"stem":"\"He ___ got a new car.\"(表''拥有''的口语说法)","options":["has","does","was","is"],"answer_index":0,"stem_cn":"他有一辆新车。","explanation_cn":"口语里\"拥有\"常说 have got,第三人称用 has got。✓ He has got a new car 他有一辆新车。✗ is / does / was:不与 got 搭配表\"拥有\"。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp2','choice','{"stem":"\"I ___ got two large baskets.\"(表''拥有''的口语说法)","options":["am","was","have","do"],"answer_index":2,"stem_cn":"我有两个大筐。","explanation_cn":"口语里\"拥有\"常说 have got,I 用 have got。✓ I have got two baskets 我有两个大筐。✗ am / do / was:不与 got 搭配表\"拥有\"。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp3','choice','{"stem":"\"We went to ___ a look at the snake charmer.\"(看一看)","options":["have","do","give","make"],"answer_index":0,"stem_cn":"我们去看一看那个耍蛇人。","explanation_cn":"have + 名词代替动词,have a look = 看一看。✓ have a look at him 看看他。✗ do / make / give a look:搭配不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp3','choice','{"stem":"\"We ___ a good time at the party.\"(玩得开心)","options":["did","had","gave","made"],"answer_index":1,"stem_cn":"我们在聚会上玩得很开心。","explanation_cn":"have a good time = 玩得开心。✓ We had a good time 我们玩得很开心。✗ did / made / gave a good time:搭配不对。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp3','choice','{"stem":"\"He wanted to ___ a drink of water.\"(喝点水)","options":["make","do","have","give"],"answer_index":2,"stem_cn":"他想喝点水。","explanation_cn":"have a drink = 喝一杯 / 喝点。✓ have a drink of water 喝点水。✗ do / make / give a drink:搭配不对。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp3','choice','{"stem":"\"Let''s ___ a talk about it tomorrow.\"(谈一谈)","options":["do","have","say","make"],"answer_index":1,"stem_cn":"我们明天谈一谈这件事。","explanation_cn":"have a talk = 谈一谈。✓ have a talk about it 谈谈这件事。✗ do / make / say a talk:搭配不对。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp4','choice','{"stem":"\"We ___ lunch at a small restaurant.\"(吃午饭)","options":["gave","made","did","had"],"answer_index":3,"stem_cn":"我们在一家小餐馆吃了午饭。","explanation_cn":"have lunch = 吃午饭(have + 一餐)。✓ We had lunch 我们吃了午饭。✗ did / made / gave lunch:搭配不对。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp4','choice','{"stem":"\"They ___ a party last night.\"(办聚会)","options":["made","had","gave","did"],"answer_index":1,"stem_cn":"他们昨晚办了个聚会。","explanation_cn":"have a party = 办聚会。✓ They had a party 他们办了聚会。✗ did / made / gave a party:搭配不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp4','choice','{"stem":"\"Did you ___ breakfast this morning?\"(吃早饭)","options":["make","give","do","have"],"answer_index":3,"stem_cn":"你今天早上吃早饭了吗?","explanation_cn":"have breakfast = 吃早饭。✓ have breakfast 吃早饭。✗ do / make / give breakfast:搭配不对。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp5','choice','{"stem":"\"He ___ a long pipe covered with coins.\"(拿起)","options":["took off","picked up","put up","picked out"],"answer_index":1,"stem_cn":"他拿起一根缠满硬币的长管。","explanation_cn":"pick up 表\"拿起\"。✓ He picked up a long pipe 他拿起一根长管。✗ picked out:是\"挑选\";✗ put up:是\"举起/搭建\";✗ took off:是\"脱下/起飞\"。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp5','choice','{"stem":"\"I ___ a lot of English while I was in England.\"(学会,在语言环境里习得)","options":["gave up","put up","picked up","picked out"],"answer_index":2,"stem_cn":"在英国时我学会了不少英语。","explanation_cn":"pick up 也可表\"(无意中)学会\"。✓ I picked up a lot of English 我学会了不少英语。✗ picked out:挑选;✗ put up:举起;✗ gave up:放弃。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp6','choice','{"stem":"\"There are so many cards; I can''t ___ the ones I like.\"(挑选、选出)","options":["pick out","put out","take out","pick up"],"answer_index":0,"stem_cn":"卡片太多,我挑不出喜欢的。","explanation_cn":"pick out 表\"挑选、选出\"。✓ pick out the ones I like 挑出我喜欢的。✗ pick up:拿起;✗ put out:扑灭;✗ take out:取出。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp7','choice','{"stem":"\"The snake could not ___ between Indian music and jazz.\"(辨别…之间的不同)","options":["make the difference","tell the difference","do the difference","take the difference"],"answer_index":1,"stem_cn":"那蛇分辨不出印度音乐和爵士乐。","explanation_cn":"\"辨别……之间的不同\"用 tell the difference between。✓ tell the difference between music and jazz 分辨音乐和爵士乐。✗ make / take / do the difference:搭配不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp7','choice','{"stem":"\"Can you ___ between the two colors?\"(辨别…之间的不同)","options":["make the difference","take the difference","tell the difference","say the difference"],"answer_index":2,"stem_cn":"你能分辨这两种颜色吗?","explanation_cn":"辨别不同用 tell the difference between。✓ tell the difference between the two colors 分辨两种颜色。✗ make / take / say the difference:搭配不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp8','choice','{"stem":"\"___ he saw us, he opened one of the baskets.\"(一…就…)","options":["So that","As soon as","Even if","As long as"],"answer_index":1,"stem_cn":"他一看见我们,就打开了一个筐。","explanation_cn":"\"一…就…\"用 as soon as。✓ As soon as he saw us 他一看见我们。✗ As long as:只要;✗ So that:以便;✗ Even if:即使。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',5,'am2_l42_gp8','choice','{"stem":"\"I''ll call you ___ I arrive.\"(一…就…)","options":["so that","even if","as long as","as soon as"],"answer_index":3,"stem_cn":"我一到就给你打电话。","explanation_cn":"\"一…就…\"用 as soon as。✓ as soon as I arrive 我一到就…。✗ as long as:只要;✗ so that:以便;✗ even if:即使。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',6,NULL,'choice','{"stem":"美语里\"散步\"更常说:","options":["make a walk","have a walk","do a walk","take a walk"],"answer_index":3,"explanation_cn":"美语\"散步\"常说 take a walk;英式说 have a walk。✓ take a walk 散步。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',6,NULL,'choice','{"stem":"美语里\"洗澡\"更常说:","options":["take a bath","make a bath","have a bath","do a bath"],"answer_index":0,"explanation_cn":"美语\"洗澡\"常说 take a bath;英式说 have a bath。✓ take a bath 洗澡。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',6,NULL,'choice','{"stem":"musical 的意思是:","options":["吵闹的","安静的","精通音乐的;音乐的","古老的"],"answer_index":2,"explanation_cn":"musical = 精通音乐的;音乐的。✓ Not very musical 并非很懂音乐。\n顺带记:安静的 = quiet;吵闹的 = noisy;古老的 = ancient."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',6,NULL,'choice','{"stem":"glimpse 的意思是:","options":["长时间凝视","一瞥,一看","声音","气味"],"answer_index":1,"explanation_cn":"glimpse = 一瞥、一看。✓ our first glimpse 第一次瞥见。\n顺带记:长时间凝视 = stare;声音 = sound;气味 = smell."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',6,NULL,'choice','{"stem":"obviously 的意思是:","options":["偶然地","缓慢地","秘密地","显然地"],"answer_index":3,"explanation_cn":"obviously = 显然地。✓ It obviously could not tell 显然它分辨不出。\n顺带记:偶然地 = by chance;秘密地 = secretly;缓慢地 = slowly."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',6,NULL,'choice','{"stem":"continue 的意思是:","options":["结束","继续","开始","停止"],"answer_index":1,"explanation_cn":"continue = 继续。✓ continued to ''dance'' 继续\"舞动\"。\n顺带记:停止 = stop;开始 = begin;结束 = end."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',7,NULL,'cloze','{"stem":"第 1 空","context":"In a market of Old Delhi, we saw a snake charmer. We went to ___1___ a look at him. He ___2___ got two large baskets and a long pipe. We ___3___ a good time watching the snake. But it could not ___4___ the difference between Indian music and jazz.","blank_no":1,"options":["have","do","make","give"],"answer_index":0,"explanation_cn":"have a look = 看一看。✓ We went to have a look at him 我们去看看他。\n✗ do / make / give a look:搭配不对。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',7,NULL,'cloze','{"stem":"第 2 空","context":"In a market of Old Delhi, we saw a snake charmer. We went to ___1___ a look at him. He ___2___ got two large baskets and a long pipe. We ___3___ a good time watching the snake. But it could not ___4___ the difference between Indian music and jazz.","blank_no":2,"options":["has","is","does","was"],"answer_index":0,"explanation_cn":"\"拥有\"用 have got,第三人称 has got。✓ He has got two large baskets 他有两个大筐。\n✗ is / does / was:不与 got 搭配表\"拥有\"。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',7,NULL,'cloze','{"stem":"第 3 空","context":"In a market of Old Delhi, we saw a snake charmer. We went to ___1___ a look at him. He ___2___ got two large baskets and a long pipe. We ___3___ a good time watching the snake. But it could not ___4___ the difference between Indian music and jazz.","blank_no":3,"options":["had","did","made","took"],"answer_index":0,"explanation_cn":"have a good time = 玩得开心。✓ We had a good time watching 我们看得很开心。\n✗ did / made / took a good time:搭配不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',7,NULL,'cloze','{"stem":"第 4 空","context":"In a market of Old Delhi, we saw a snake charmer. We went to ___1___ a look at him. He ___2___ got two large baskets and a long pipe. We ___3___ a good time watching the snake. But it could not ___4___ the difference between Indian music and jazz.","blank_no":4,"options":["tell","make","take","do"],"answer_index":0,"explanation_cn":"\"辨别……之间的不同\"用 tell the difference between。✓ tell the difference between Indian music and jazz。\n✗ make / take / do the difference:搭配不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',8,NULL,'choice','{"stem":"Where did the travelers stop to rest?","options":["In a music hall","On a train","At a hotel","At a square in a market of Old Delhi"],"answer_index":3,"explanation_cn":"课文说 we stopped at a square to have a rest,他们在旧德里集市的广场停下休息。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',8,NULL,'choice','{"stem":"What did the snake charmer do when he saw the travelers?","options":["He asked for money first","He ran away","He picked up a pipe and opened a basket","He put the snake back"],"answer_index":2,"explanation_cn":"课文说 he picked up a long pipe… and opened one of the baskets,他拿起长管、掀开筐。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',8,NULL,'choice','{"stem":"What surprised the travelers?","options":["The snake bit someone","The charmer suddenly played jazz and pop songs","The pipe was broken","The basket was empty"],"answer_index":1,"explanation_cn":"课文说 the snake charmer suddenly began to play jazz and modern pop songs,这让旅人非常惊奇。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',9,NULL,'choice','{"stem":"你想说\"我们停下来看一看\"(用 have + 名词表''看一看''):","options":["We stopped to have a see.","We stopped to make a look.","We stopped to have a look.","We stopped to do a look."],"answer_index":2,"explanation_cn":"have + 名词代替动词,have a look = 看一看。✓ We stopped to have a look. 场合:说停下来看一眼。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',9,NULL,'choice','{"stem":"你想说\"他有一辆新车\"(口语''拥有''用 have got):","options":["He has got a new car.","He is got a new car.","He has get a new car.","He have got a new car."],"answer_index":0,"explanation_cn":"口语里\"拥有\"用 have got,第三人称 has got。✓ He has got a new car. 场合:口语说某人有某物。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',9,NULL,'choice','{"stem":"你想说\"它分辨不出两者的不同\"(辨别用 tell the difference):","options":["It could not make the difference between them.","It could not say the difference between them.","It could not take the difference between them.","It could not tell the difference between them."],"answer_index":3,"explanation_cn":"\"辨别……之间的不同\"用 tell the difference between。✓ It could not tell the difference between them. 场合:说分辨不出两者。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"glimpse 的意思是:","options":["长久凝视","气味","一瞥,一看","声音"],"answer_index":2,"explanation_cn":"glimpse = 一瞥、一看。✓ first glimpse 第一次瞥见。\n顺带记:长久凝视 = stare;气味 = smell;声音 = sound."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"obviously 的意思是:","options":["显然地","偶然地","缓慢地","秘密地"],"answer_index":0,"explanation_cn":"obviously = 显然地。✓ obviously could not tell 显然分辨不出。\n顺带记:偶然地 = by chance;缓慢地 = slowly;秘密地 = secretly."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"\"We went to ___ a look at the snake charmer.\"(看一看,填代替动词的那个词)","options":["do","make","have","give"],"answer_index":2,"stem_cn":"我们去看一看那个耍蛇人。","explanation_cn":"have a look = 看一看(have + 名词代替动词)。✓ have a look at the snake charmer 看看耍蛇人。\n✗ do / make / give a look:搭配不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"\"He ___ got two large baskets.\"(口语''拥有'')","options":["was","has","is","does"],"answer_index":1,"stem_cn":"他有两个大筐。","explanation_cn":"口语里\"拥有\"用 have got,第三人称 has got。✓ He has got two large baskets 他有两个大筐。\n✗ is / does / was:不与 got 搭配表\"拥有\"。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"\"It obviously could not tell the difference between Indian music and jazz.\" 这句话的意思是:","options":["显然,它分辨不出印度音乐和爵士乐。","它显然更喜欢爵士乐。","它听不见任何音乐。","它会随着音乐跳舞。"],"answer_index":0,"explanation_cn":"It obviously could not tell the difference between Indian music and jazz. obviously = 显然,tell the difference = 辨别,意思是\"显然,它分辨不出印度音乐和爵士乐\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"\"As soon as he saw us, he opened one of the baskets.\" 这句话的意思是:","options":["他请我们打开筐。","他看见我们后很久才打开筐。","他没看见我们就走了。","他一看见我们,就打开了一个筐。"],"answer_index":3,"explanation_cn":"As soon as he saw us, he opened one of the baskets. as soon as = \"一…就…\",意思是\"他一看见我们,就打开了一个筐\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"Why did the travelers go over to the snake charmer?","options":["He called them over","They wanted to buy a snake","They noticed him and wanted to have a look","They were lost"],"answer_index":2,"passage":"As we had had a long walk through one of the markets of Old Delhi, we stopped at a square to have a rest. After a time, we noticed a snake charmer with two large baskets at the other side of the square, so we went to have a look at him. As soon as he saw us, he picked up a long pipe which was covered with coins and opened one of the baskets. When he began to play a tune, we had our first glimpse of the snake. It rose out of the basket and began to follow the movements of the pipe. We were very much surprised when the snake charmer suddenly began to play jazz and modern pop songs. The snake, however, continued to ''dance'' slowly. It obviously could not tell the difference between Indian music and jazz!","explanation_cn":"课文说 we noticed a snake charmer… so we went to have a look at him,他们注意到便走过去看。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"How did the snake react to the jazz music?","options":["It continued to ''dance'' slowly, as before","It danced much faster","It went back into the basket","It stopped dancing at once"],"answer_index":0,"passage":"As we had had a long walk through one of the markets of Old Delhi, we stopped at a square to have a rest. After a time, we noticed a snake charmer with two large baskets at the other side of the square, so we went to have a look at him. As soon as he saw us, he picked up a long pipe which was covered with coins and opened one of the baskets. When he began to play a tune, we had our first glimpse of the snake. It rose out of the basket and began to follow the movements of the pipe. We were very much surprised when the snake charmer suddenly began to play jazz and modern pop songs. The snake, however, continued to ''dance'' slowly. It obviously could not tell the difference between Indian music and jazz!","explanation_cn":"课文说 The snake, however, continued to ''dance'' slowly,蛇照旧慢慢舞动。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"What did the snake charmer play at first?","options":["Jazz music","A pop song","A drum","A tune on his pipe"],"answer_index":3,"audio":"As we had had a long walk through one of the markets of Old Delhi, we stopped at a square to have a rest. After a time, we noticed a snake charmer with two large baskets at the other side of the square, so we went to have a look at him. As soon as he saw us, he picked up a long pipe which was covered with coins and opened one of the baskets. When he began to play a tune, we had our first glimpse of the snake. It rose out of the basket and began to follow the movements of the pipe. We were very much surprised when the snake charmer suddenly began to play jazz and modern pop songs. The snake, however, continued to ''dance'' slowly. It obviously could not tell the difference between Indian music and jazz!","explanation_cn":"课文说 When he began to play a tune,耍蛇人先在管子上吹一支曲子。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l42',10,NULL,'choice','{"stem":"What does the title ''Not very musical'' refer to?","options":["The charmer sang badly","The travelers hated music","The snake could not really tell one kind of music from another","The pipe was out of tune"],"answer_index":2,"audio":"As we had had a long walk through one of the markets of Old Delhi, we stopped at a square to have a rest. After a time, we noticed a snake charmer with two large baskets at the other side of the square, so we went to have a look at him. As soon as he saw us, he picked up a long pipe which was covered with coins and opened one of the baskets. When he began to play a tune, we had our first glimpse of the snake. It rose out of the basket and began to follow the movements of the pipe. We were very much surprised when the snake charmer suddenly began to play jazz and modern pop songs. The snake, however, continued to ''dance'' slowly. It obviously could not tell the difference between Indian music and jazz!","explanation_cn":"标题 Not very musical 指蛇并不真懂音乐——它分辨不出印度音乐和爵士乐。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
